syntax:
template< class Container >
std::insert_iterator<Container> front_inserter(Container& c);
// Implementation notes: This returns std::insert_iterator<Container>(c, &Container::push_front), where the iterator's operator= calls c.push_front(value), ensuring elements are prepended to the container at runtime.

code_example:
#include <iterator>
#include <deque>
#include <iostream>

int main() {
    std::deque<int> coll;  // A double-ended queue with efficient front insertion
    auto inserter = std::front_inserter(coll);  // Creates an insert_iterator
    *inserter = 42;  // Inserts 42 at the front of coll
    *inserter = 24;  // Inserts 24 at the front, so coll is now {24, 42}
    for (const auto& elem : coll) {
        std::cout << elem << ' ';  // Outputs: 24 42
    }
    std::cout << std::endl;
    return 0;
}
